import { db2 } from "@/db";
import { sql } from "drizzle-orm";

/**
 * Idempotent bootstrap for the DB2 inventory/catalogue tables.
 *
 * DB2 owns: categories, products, accounts, uc_packages, special_products,
 * coupons, site_settings, feedbacks and the legacy `feedback` table.
 * Every DB2 route calls `ensureStoreTables()` before touching these tables so
 * a brand-new Neon database is provisioned automatically on first request.
 * Nothing is ever dropped or overwritten.
 *
 * The canonical DDL also lives in `drizzle/db2/` (generated by drizzle-kit).
 */
type G = typeof globalThis & { __bgmiStoreTablesReady?: Promise<boolean> };

const STATEMENTS = [
  `CREATE TABLE IF NOT EXISTS categories (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name varchar(100) NOT NULL,
    slug varchar(100) NOT NULL UNIQUE,
    description text,
    image text,
    sort_order integer NOT NULL DEFAULT 100,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
  )`,
  `CREATE TABLE IF NOT EXISTS products (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    category_slug varchar(100) NOT NULL,
    title varchar(180) NOT NULL,
    price integer NOT NULL,
    image text NOT NULL,
    features jsonb NOT NULL DEFAULT '[]'::jsonb,
    badge varchar(48),
    sort_order integer NOT NULL DEFAULT 0,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
  )`,
  `CREATE INDEX IF NOT EXISTS products_category_idx ON products (category_slug, sort_order)`,
  `CREATE TABLE IF NOT EXISTS accounts (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    title varchar(180) NOT NULL,
    price integer NOT NULL,
    image text NOT NULL,
    features jsonb NOT NULL DEFAULT '[]'::jsonb,
    badge varchar(48),
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
  )`,
  `CREATE TABLE IF NOT EXISTS uc_packages (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    price integer NOT NULL,
    uc_amount integer NOT NULL,
    bonus_label varchar(80),
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now()
  )`,
  `CREATE TABLE IF NOT EXISTS special_products (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    category varchar(20) NOT NULL,
    title varchar(180) NOT NULL,
    price integer NOT NULL,
    image text NOT NULL,
    features jsonb NOT NULL DEFAULT '[]'::jsonb,
    badge varchar(48),
    sort_order integer NOT NULL DEFAULT 0,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
  )`,
  `CREATE TABLE IF NOT EXISTS coupons (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    code varchar(50) NOT NULL UNIQUE,
    discount_type varchar(12) NOT NULL DEFAULT 'percent',
    discount_value integer NOT NULL,
    usage_limit integer,
    usage_count integer NOT NULL DEFAULT 0,
    expires_at timestamptz,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now()
  )`,
  `CREATE TABLE IF NOT EXISTS site_settings (
    setting_key varchar(80) PRIMARY KEY,
    value jsonb NOT NULL,
    updated_at timestamptz NOT NULL DEFAULT now()
  )`,
  `CREATE TABLE IF NOT EXISTS feedbacks (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name varchar(120) NOT NULL,
    review text NOT NULL,
    rating integer NOT NULL DEFAULT 5,
    avatar text,
    is_active boolean NOT NULL DEFAULT true,
    status varchar(16) NOT NULL DEFAULT 'pending',
    submitted_by_email varchar(180),
    moderated_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
  )`,
  `CREATE INDEX IF NOT EXISTS feedbacks_status_idx ON feedbacks (status)`,
  `CREATE INDEX IF NOT EXISTS feedbacks_created_at_idx ON feedbacks (created_at DESC)`,
  `CREATE TABLE IF NOT EXISTS feedback (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    type varchar(20) NOT NULL,
    author varchar(100),
    body text NOT NULL,
    rating integer,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now()
  )`,
];

export function ensureStoreTables(): Promise<boolean> {
  const g = globalThis as G;
  if (g.__bgmiStoreTablesReady) return g.__bgmiStoreTablesReady;

  g.__bgmiStoreTablesReady = (async () => {
    try {
      for (const statement of STATEMENTS) {
        await db2.execute(sql.raw(statement));
      }
      return true;
    } catch {
      // Database unreachable — retry on the next request.
      g.__bgmiStoreTablesReady = undefined;
      return false;
    }
  })();

  return g.__bgmiStoreTablesReady;
}
